import { describe, expect, it } from "vitest";
import { AGENT_LABELS, AGENT_TYPES, agentForTarget, isAgentType, isTargetName, TARGET_NAMES, targetForAgent, } from "./agentHosts.js";
describe("agent hosts", () => {
    it("pairs every skill target with exactly one chat session agent", () => {
        expect(TARGET_NAMES).toHaveLength(AGENT_TYPES.length);
        expect(TARGET_NAMES.map(agentForTarget).sort()).toEqual([...AGENT_TYPES].sort());
    });
    it("round-trips a target through its agent and back", () => {
        for (const target of TARGET_NAMES) {
            expect(targetForAgent(agentForTarget(target))).toBe(target);
        }
    });
    it("keeps Claude Code's agent id distinct from its target name", () => {
        expect(agentForTarget("claude")).toBe("claude-code");
        expect(targetForAgent("claude-code")).toBe("claude");
    });
    it("labels every agent", () => {
        for (const agent of AGENT_TYPES) {
            expect(AGENT_LABELS[agent]).toBeTruthy();
        }
    });
    it("narrows only known values", () => {
        expect(isAgentType("amp")).toBe(true);
        expect(isAgentType("claude")).toBe(false);
        expect(isTargetName("claude")).toBe(true);
        expect(isTargetName("claude-code")).toBe(false);
    });
});
